/**
 * The apps are generated by a person, one platform at a time, and carry no platform brand.
 *   npx tsx --require ./scripts/lib/next-server-shims.cjs scripts/test-apps-manual.ts
 */
import assert from "node:assert/strict";
import { APP_PLATFORMS, PLATFORM_META, SCOPE_PLATFORMS, isAppPlatform } from "../src/lib/apps/types";
import { emptyPlatforms, overallStatus, platformsOf } from "../src/lib/apps/status";
import { DEFAULT_APP_SETTINGS, normalizeAppSettings } from "../src/lib/pwa/settings";

let n = 0;
const ok = (name: string, fn: () => void) => { fn(); n++; console.log(`✓ ${name}`); };

ok("every platform has its own scope and its own Generate button text", () => {
  for (const p of APP_PLATFORMS) {
    assert.deepEqual([...SCOPE_PLATFORMS[p]], [p]);
    assert.equal(PLATFORM_META[p].cta, `Generate ${PLATFORM_META[p].label} App`);
  }
  assert.equal(PLATFORM_META.android.cta, "Generate Android App");
  assert.equal(PLATFORM_META.ios.cta, "Generate iOS App");
  assert.equal(PLATFORM_META.linux.cta, "Generate Linux App");
  assert.equal(PLATFORM_META.win.cta, "Generate Windows App");
  assert.equal(PLATFORM_META.mac.cta, "Generate macOS App");
});

ok("a single-platform build waits for that platform only; the others are skipped", () => {
  const b = { platforms: emptyPlatforms("android"), dispatchedAt: null as Date | null };
  assert.equal(b.platforms.android.status, "queued");
  for (const p of APP_PLATFORMS.filter((x) => x !== "android")) assert.equal(b.platforms[p].status, "skipped");
  assert.equal(overallStatus(b), "queued");
  b.dispatchedAt = new Date();
  assert.equal(overallStatus(b), "building");
  b.platforms.android.status = "ready";
  assert.equal(overallStatus(b), "ready");
});

ok("a failed platform makes only that build failed", () => {
  const b = { platforms: emptyPlatforms("ios"), dispatchedAt: new Date() };
  b.platforms.ios.status = "failed";
  assert.equal(overallStatus(b), "failed");
  assert.equal(platformsOf(b).win.status, "skipped");
});

ok("only real platform names are accepted", () => {
  assert.ok(isAppPlatform("linux"));
  for (const bad of ["desktop", "mobile", "all", "", "windows", "ios; rm", 7, null, undefined]) assert.equal(isAppPlatform(bad as unknown), false);
});

ok("settings no longer carry an automatic switch; old saved values are ignored", () => {
  const s = normalizeAppSettings({ generation: { automatic: true }, desktop: { autoRebuild: true, closeToTray: false } });
  assert.equal("generation" in s, false);
  assert.equal("autoRebuild" in s.desktop, false);
  assert.equal(s.desktop.closeToTray, false);
  assert.equal("generation" in DEFAULT_APP_SETTINGS, false);
});

console.log(`\n${n} checks passed.`);
